const projects=[{title:'Forma — a quieter kind of commerce',description:'An illustrative storefront concept for considered everyday objects. Warm neutrals, generous space, and sculptural product compositions create a calm browsing experience.',focus:'Art direction / Interface design'},{title:'Orbit — a little more headspace',description:'An illustrative workspace dashboard exploring how thoughtful hierarchy can make complex information easier to navigate. Soft color, clear activity summaries, and restrained components keep the interface focused.',focus:'Product design / Frontend development'},{title:'Offscript — a different perspective',description:'An illustrative editorial identity for an independent culture journal. Expressive typography and a confident orange palette give stories their own distinct point of view.',focus:'Identity / Web design / Development'}];
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(other=>{const selected=other===button;other.classList.toggle('active',selected);other.setAttribute('aria-pressed',selected)});document.querySelectorAll('[data-project]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&!card.dataset.category.split(' ').includes(button.dataset.filter))}));
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-project]').forEach(card=>card.addEventListener('click',()=>{const project=projects[Number(card.dataset.project)];document.querySelector('#dialog-title').textContent=project.title;document.querySelector('#dialog-description').textContent=project.description;document.querySelector('#dialog-focus').textContent=project.focus;dialog.showModal()}));document.querySelectorAll('.close,.dialog-done').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
try{if(localStorage.getItem('portfolio-theme')==='dark')document.body.classList.add('dark')}catch{}document.querySelector('.theme').addEventListener('click',()=>{const dark=document.body.classList.toggle('dark');try{localStorage.setItem('portfolio-theme',dark?'dark':'light')}catch{}});document.querySelector('#year').textContent=new Date().getFullYear();
